insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (64, 'Williams College', '윌리엄스 칼리지', 1, 1, 1490, 1550, '석차 제출 신입생 중 88%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 17%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 석차, 학업 GPA, 추천서, 인성/개인 자질입니다(에세이·과외활동·재능은 Important, 표준화 시험은 Considered). 입학처는 "We take a holistic approach to reviewing applications that aims at understanding all the many ways an applicant might impact and enhance our community"라고 공식 명시하며, CDS C8에는 "Williams is truly test optional"이라고 적고 있습니다.', 'https://www.williams.edu/admission-aid/apply-overview/', 'test-optional', '매사추세츠주 윌리엄스타운에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '버크셔 산지의 작은 대학 마을로 보스턴에서 서쪽으로 약 220km(차로 약 3시간), 뉴욕시에서 약 260km 거리이며, 겨울이 길고 눈이 많은 산악 기후입니다.', true, false, false, false, '11월 중순', NULL, NULL, '1월 초', 'https://www.williams.edu/admission-aid/apply-overview/', '2026-08-22', ARRAY['rigor','class_rank','gpa','recommendations','character']::text[], 'https://hub.williams.edu/institutional-research/files/2026/04/Williams-CDS-2025-2026-V2.pdf', 'lac', 1, 'A small private liberal arts college located in Williamstown, Massachusetts.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, class rank, academic GPA, recommendations, and character/personal qualities (essay, extracurriculars and talent are Important; standardized tests are Considered). The admission office officially states, "We take a holistic approach to reviewing applications that aims at understanding all the many ways an applicant might impact and enhance our community," and CDS C8 notes "Williams is truly test optional."', 'A small college town in the Berkshire hills about 220 km (roughly 3 hours by car) west of Boston and about 260 km from New York City; mountain climate with long, snowy winters.', '88% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 17% submitted rank)', 123, 94807, '2025-26', true, NULL, true, true, '공식 국제학생 재정지원 페이지: "Although Williams isn''t need-blind for international applicants, approximately 70% of international students receive financial aid from the college, with aid awards averaging more than $90,000 annually... Financial aid awards for international students are comprehensive, meet 100% of demonstrated need and are guaranteed for all four years." All-Grant 프로그램으로 "loans will never be included in your financial aid award from Williams." 메리트 장학금은 없으며(CDS H6: 비거주자에게 need-based 지원만 제공) 모든 지원은 니드 기반입니다. 국제학생은 입학 지원서에서 재정지원 신청 의사를 반드시 표시해야 합니다.', 'https://www.williams.edu/admission-aid/financial-aid/international/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (65, 'Amherst College', '애머스트 칼리지', 2, 1, 1470, 1540, '석차 제출 신입생 중 88%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 28%)', NULL, true, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 학업 GPA, 표준화 시험 점수, 에세이, 추천서, 과외활동, 재능/능력입니다(인성·1세대·봉사·근로경험은 Important). 입학처는 국제학생 페이지에서 "Amherst College follows a need-blind admission policy for all students—domestic and international"이라고 공식 명시하며, 표준화 시험은 "Optional Standardized Test Results for the SAT or ACT"로 선택 제출입니다.', 'https://www.amherst.edu/admission/apply/firstyear', 'test-optional', '매사추세츠주 애머스트에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '매사추세츠 서부 파이오니어 밸리의 대학 소도시(UMass 등 5개 대학 컨소시엄)로 보스턴에서 서쪽으로 약 150km(차로 약 2시간) 거리이며, 사계절이 뚜렷하고 겨울은 춥고 눈이 옵니다.', true, false, false, false, '11월 초', NULL, NULL, '1월 초', 'https://www.amherst.edu/admission/apply/firstyear/calendar_deadlines', '2026-08-22', ARRAY['rigor','gpa','standardized_tests','essay','recommendations','extracurricular','talent']::text[], 'https://www.amherst.edu/system/files/C.%20First-Time%20First-Year%20Admission%202025-26_0.pdf', 'lac', 2, 'A small private liberal arts college located in Amherst, Massachusetts.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, standardized test scores, application essay, recommendations, extracurricular activities, and talent/ability (character, first generation, volunteer work and work experience are Important). The admission office officially states on its international page that "Amherst College follows a need-blind admission policy for all students—domestic and international," and standardized tests are "Optional Standardized Test Results for the SAT or ACT."', 'A college town in western Massachusetts'' Pioneer Valley (part of the Five College Consortium with UMass), about 150 km (roughly 2 hours by car) west of Boston; four distinct seasons with cold, snowy winters.', '88% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 28% submitted rank)', 204, 84590, '2025-26', true, NULL, true, true, '공식 국제학생 페이지: "Amherst College follows a need-blind admission policy for all students—domestic and international... Amherst meets 100% of calculated financial need for all international students who are admitted to the college and apply for need-based financial aid." 같은 페이지에 "100% Calculated financial need met; no loans required", "82% International students with aid, 2025-2026", "$84,000+ Average international financial aid award, 2025–2026" 명시. 재정지원 페이지: "we pride ourselves on being a no-loan school". 메리트 장학금은 없으며(CDS H6: 비거주자에게 need-based 지원만 제공) 모든 지원은 니드 기반입니다.', 'https://www.amherst.edu/admission/apply/international') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (66, 'Swarthmore College', '스워스모어 칼리지', 4, 1, 1480, 1550, '석차 제출 신입생 중 87%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 30%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 석차, 학업 GPA, 에세이, 추천서, 인성/개인 자질입니다(표준화 시험·과외활동·재능은 Considered). 입학처는 "At Swarthmore, we practice holistic and contextual admissions... we do not make admissions decisions based on just one factor like a test score"라고 공식 명시하며, "Submitting standardized testing scores is optional and you will not be penalized in your admissions review if you do not submit scores"라고 밝힙니다.', 'https://www.swarthmore.edu/admissions-aid/standardized-testing-policy', 'test-optional', '펜실베이니아주 스워스모어에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '필라델피아 근교의 작은 교외 마을로 필라델피아 도심까지 약 18km(통근열차 약 30분) 거리이며, 여름은 덥고 습하며 겨울은 비교적 온화하지만 눈이 올 수 있습니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.swarthmore.edu/admissions-aid/application-materials-deadlines', '2026-08-22', ARRAY['rigor','class_rank','gpa','essay','recommendations','character']::text[], 'https://www.swarthmore.edu/sites/default/files/assets/documents/institutional-effectiveness-research-assessment/Swarthmore-CDS-2025-26.pdf', 'lac', 4, 'A small private liberal arts college located in Swarthmore, Pennsylvania.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, class rank, academic GPA, application essay, recommendations, and character/personal qualities (standardized tests, extracurriculars and talent are Considered). The admission office officially states, "At Swarthmore, we practice holistic and contextual admissions... we do not make admissions decisions based on just one factor like a test score," and that "Submitting standardized testing scores is optional and you will not be penalized in your admissions review if you do not submit scores."', 'A small suburban borough about 18 km (roughly 30 minutes by commuter rail) from downtown Philadelphia; hot, humid summers and relatively mild winters with occasional snow.', '87% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 30% submitted rank)', 75, 87434, '2024-25', true, NULL, true, true, '공식 국제학생 페이지: "Admission to Swarthmore is need-aware for international citizens (excluding Permanent Residents, dual U.S. citizens, and DACA and undocumented students...)" / "if Swarthmore admits you and you applied for financial aid, the College meets 100% of your institutionally-determined financial need" / "Swarthmore is one of a small number of U.S. institutions that meets 100% of institutionally-determined financial need and does not include loans in the financial aid it offers to international students." 메리트 장학금 언급 없음(CDS H6: 비거주자에게 need-based 지원만 제공).', 'https://www.swarthmore.edu/admissions-aid/international-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (67, 'Bowdoin College', '보든 칼리지', 5, 1, 1470, 1540, '석차 제출 신입생 중 89%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 27%)', NULL, true, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 석차, 학업 GPA, 에세이, 추천서, 과외활동, 재능/능력, 인성/개인 자질입니다(지원자의 관심도는 Considered). 입학처는 "Bowdoin seeks students who are bright and engaged inside and outside the classroom, and who demonstrate curiosity and a willingness to take intellectual risks"라고 공식 명시하며, "Of the credentials Bowdoin evaluates, a student''s overall academic record is by far the most important"이라고 밝힙니다.', 'https://www.bowdoin.edu/admissions/apply/index.html', 'test-optional', '메인주 브런즈윅에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '메인주 해안의 작은 마을로 포틀랜드(메인)에서 북쪽으로 약 45km, 보스턴에서 약 200km(차로 약 2시간 반) 거리이며, 겨울이 길고 춥고 눈이 많습니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.bowdoin.edu/admissions/apply/dates-deadlines/index.html', '2026-08-22', ARRAY['rigor','class_rank','gpa','essay','recommendations','extracurricular','talent','character']::text[], 'https://www.bowdoin.edu/ir/pdf/bowdoin-cds_2025-2026.pdf', 'lac', 5, 'A small private liberal arts college located in Brunswick, Maine.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, class rank, academic GPA, application essay, recommendations, extracurricular activities, talent/ability, and character/personal qualities (level of applicant''s interest is Considered). The admission office officially states, "Bowdoin seeks students who are bright and engaged inside and outside the classroom, and who demonstrate curiosity and a willingness to take intellectual risks," and that "Of the credentials Bowdoin evaluates, a student''s overall academic record is by far the most important."', 'A small coastal Maine town about 45 km north of Portland, Maine and about 200 km (roughly 2.5 hours by car) from Boston; long, cold, snowy winters.', '89% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 27% submitted rank)', 102, 84882, '2024-25', true, NULL, true, true, '공식 국제학생 페이지: "Bowdoin College is need blind for international students. That means your family''s ability to pay is not a factor or barrier to admission." / "Bowdoin is one of only eleven colleges and universities in the U.S. that are need-blind...and meets the full calculated need of every student we admit, including international students." / "$0 amount of loans in our financial aid packages." 학자금지원 페이지: "Our aid packages are loan free". 메리트 장학금 언급 없음(CDS H6: 비거주자에게 need-based 지원만 제공).', 'https://www.bowdoin.edu/admissions/apply/international-students/index.html') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (68, 'Claremont McKenna College', '클레어몬트 매케나 칼리지', 7, 1, 1480, 1540, '석차 제출 신입생 중 64%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 15%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 학업 GPA, 에세이, 추천서, 과외활동, 인성/개인 자질입니다(인터뷰·재능은 Important, 석차·표준화 시험은 Considered). 입학처는 "Admission to CMC is based on a holistic review process that considers a broad range of factors, including a prospective student''s academic and leadership achievements, commitment to CMC''s values, and potential to benefit from and contribute to CMC''s mission"이라고 공식 명시합니다.', 'https://www.cmc.edu/admission/apply', 'test-optional', '캘리포니아주 클레어몬트에 위치한 소규모 사립 리버럴 아츠 칼리지로, 클레어몬트 컬리지 컨소시엄(5C)의 일원입니다.', '로스앤젤레스 동쪽 약 55km(차로 약 1시간)의 교외 대학 도시로, 연중 온화하고 건조한 지중해성 기후이며 여름은 덥습니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://www.cmc.edu/admission/first-year-application-instructions', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations','extracurricular','character']::text[], 'https://www.cmc.edu/sites/default/files/CDS_2025-26.pdf', 'lac', 7, 'A small private liberal arts college located in Claremont, California, and a member of the Claremont Colleges consortium.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, application essay, recommendations, extracurricular activities, and character/personal qualities (interview and talent are Important; class rank and standardized tests are Considered). The admission office officially states, "Admission to CMC is based on a holistic review process that considers a broad range of factors, including a prospective student''s academic and leadership achievements, commitment to CMC''s values, and potential to benefit from and contribute to CMC''s mission."', 'A suburban college town about 55 km (roughly 1 hour by car) east of Los Angeles; mild, dry Mediterranean climate year-round with hot summers.', '64% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 15% submitted rank)', 53, 64997, '2024-25', true, 'McKenna Scholars ($15,000), Seaver Scholars (full tuition) — 국제학생 자격 여부는 공식 페이지에 명시 없음', true, false, '공식 국제학생 지원 페이지: "CMC is need-aware in its admission process for all international students (non-U.S. citizens and non-U.S. permanent residents)... However, if admitted, CMC is committed to meeting demonstrated need as determined at the time of admission." / "Merit-based scholarships are available for all first-year applicants and are determined by the Office of Admission through the application review process." 메리트 우선 심사는 12/1까지 지원. 장학금 페이지: McKenna Scholars($15,000), Seaver Scholars(full-tuition). CDS H6: 비거주자에게 need-based와 non-need-based 지원 모두 제공. 재정지원 패키지에는 론이 포함될 수 있음("grants, scholarships, work, and loans").', 'https://www.cmc.edu/admission/international') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (69, 'Pomona College', '포모나 칼리지', 7, 1, 1490, 1550, NULL, NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor)·석차·GPA·에세이·추천서·교외활동·재능·인성(character) 8가지이며, 표준화 시험은 ''Considered'', 지원자의 관심도(demonstrated interest)는 ''Not Considered''입니다. 입학처는 "we are also evaluating what and how students will contribute to Pomona College, their talents, their qualities (like grit, creativity, leadership, kindness, innovation, etc.) and their potential"이라고 공식 명시합니다.', 'https://www.pomona.edu/admissions/apply/first-year-applicants', 'test-optional', '캘리포니아주 클레어몬트에 위치한 소규모 사립 리버럴 아츠 칼리지로, 클레어몬트 칼리지 연합(5C)의 일원입니다.', '로스앤젤레스 도심에서 동쪽으로 약 55km 떨어진 소도시 클레어몬트에 있으며, 연중 온화하고 건조한 남부 캘리포니아 기후입니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://www.pomona.edu/admissions/apply/first-year-applicants', '2026-08-22', ARRAY['rigor','class_rank','gpa','essay','recommendations','extracurricular','talent','character']::text[], 'https://tableau.campus.pomona.edu/views/CDS2025-26/C_First-timeFirst-yearadmission', 'lac', 7, 'A small private liberal arts college in Claremont, California, and a member of the Claremont Colleges consortium.', 'In CDS 2025-26 C7, the eight factors officially marked ''Very Important'' are rigor of secondary school record, class rank, GPA, essay, recommendations, extracurricular activities, talent/ability and character/personal qualities; standardized tests are ''Considered'' and level of applicant''s interest is ''Not Considered''. The admissions office officially states: "we are also evaluating what and how students will contribute to Pomona College, their talents, their qualities (like grit, creativity, leadership, kindness, innovation, etc.) and their potential."', 'Located in the small city of Claremont, about 35 miles east of downtown Los Angeles, with a mild, dry Southern California climate year-round.', NULL, 98, 86889, '2024-25', true, NULL, true, true, '공식: 성적·체육 장학금 없음(need-based only). 국제학생은 need-aware 심사이나 합격자는 100% need 충족("Admissions is need-aware for international applicants, but we meet the full need of every admitted international student"). 아이드 패키지에 대출 미포함("Pomona does not use loans to meet a student''s financial need").', 'https://www.pomona.edu/admissions/apply/international-applicants') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (70, 'Wellesley College', '웰즐리 칼리지', 7, 1, 1460, 1540, '석차 제출 신입생 중 88%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출 비율 25%)', NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor)·GPA·추천서·인성(character) 4가지이며, 석차·에세이·교외활동·재능은 ''Important'', 표준화 시험과 지원자의 관심도는 ''Considered''입니다. 입학처는 "the admission committee is particularly interested in an applicant''s demonstrated writing and quantitative skills as key predictors for success in Wellesley''s curriculum"이라고 공식 명시합니다.', 'https://www.wellesley.edu/admission-aid/apply/first-year-applicants', 'test-optional', '매사추세츠주 웰즐리에 위치한 소규모 사립 여자 리버럴 아츠 칼리지입니다.', '보스턴 도심에서 서쪽으로 약 20km 떨어진 교외 소도시 웰즐리에 있으며, 사계절이 뚜렷하고 겨울이 춥고 눈이 많은 뉴잉글랜드 기후입니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://www.wellesley.edu/admission-aid/apply/first-year-applicants', '2026-08-22', ARRAY['rigor','gpa','recommendations','character']::text[], 'https://wellesley-college.files.svdcdn.com/production/administrative-departments/OIR/CDS_2025-2026-FINAL.pdf', 'lac', 7, 'A small private women''s liberal arts college in Wellesley, Massachusetts.', 'In CDS 2025-26 C7, the four factors officially marked ''Very Important'' are rigor of secondary school record, GPA, recommendations and character/personal qualities; class rank, essay, extracurricular activities and talent/ability are ''Important'', and standardized tests and level of applicant''s interest are ''Considered''. The admissions office officially states: "the admission committee is particularly interested in an applicant''s demonstrated writing and quantitative skills as key predictors for success in Wellesley''s curriculum."', 'Located in the suburban town of Wellesley, about 12 miles west of downtown Boston, with a four-season New England climate and cold, snowy winters.', '88% of enrolled first-years who submitted class rank were in the top tenth of their high school class (CDS 2025-26 C10; 25% submitted rank)', 71, 94053, '2025-26', true, NULL, true, NULL, '공식: 성적·체육 등 merit 장학금 없음("We do not offer academic, athletic or other scholarships"). 국제학생(비시민·비영주권자)은 need-blind 아님("Wellesley is not need-blind for students who are not U.S. citizens or permanent residents"), 제한된 수의 need-based 지원, 합격자는 계산된 need 100% 충족("committed to meeting 100% of calculated need for all admitted international citizens who have applied for financial aid during the admission process").', 'https://www.wellesley.edu/admission-aid/student-financial-services/understanding-financial-aid/apply-for-aid/international-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (71, 'Carleton College', '칼턴 칼리지', 10, 1, 1460, 1530, '석차 제출 신입생 중 77%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출 비율 30.5%)', NULL, NULL, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor)·석차·GPA·에세이·추천서·교외활동·재능·인성(character) 8가지이며, 표준화 시험은 ''Considered'', 지원자의 관심도는 ''Not Considered''입니다. 입학처는 "When we read your application, we want to learn about your academic achievements and personal strengths"라고 공식 명시하며, AP·IB 등 상급 과정 이수를 선호한다고 밝힙니다.', 'https://www.carleton.edu/admissions/apply/steps/criteria/', 'test-optional', '미네소타주 노스필드에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '미니애폴리스-세인트폴 대도시권에서 남쪽으로 약 65km 떨어진 소도시 노스필드에 있으며, 겨울이 길고 매우 추운 미국 중서부 대륙성 기후입니다.', true, true, false, false, '11월 중순', '1월 중순', NULL, '1월 중순', 'https://www.carleton.edu/admissions/apply/steps/materials/', '2026-08-22', ARRAY['rigor','class_rank','gpa','essay','recommendations','extracurricular','talent','character']::text[], 'https://carleton-wp-production.s3.amazonaws.com/uploads/sites/292/2026/06/CDS-PDF-2025-2026_PDF_Carleton_06242026.pdf', 'lac', 10, 'A small private liberal arts college in Northfield, Minnesota.', 'In CDS 2025-26 C7, the eight factors officially marked ''Very Important'' are rigor of secondary school record, class rank, GPA, essay, recommendations, extracurricular activities, talent/ability and character/personal qualities; standardized tests are ''Considered'' and level of applicant''s interest is ''Not Considered''. The admissions office officially states: "When we read your application, we want to learn about your academic achievements and personal strengths," and notes it is usually attracted to candidates who take honors or advanced-level work such as AP or IB when available.', 'Located in the small town of Northfield, about 40 miles south of Minneapolis–St. Paul, with a Midwestern continental climate and long, very cold winters.', '77% of enrolled first-years who submitted class rank were in the top tenth of their high school class (CDS 2025-26 C10; 30.5% submitted rank)', 63, 81596, '2025-26', true, NULL, true, false, '공식: merit 장학금 없음("We do not offer merit scholarships"; "All Carleton grants and scholarships are need-based"). 국제학생 재정지원은 재원이 제한적("We have limited funding available to international students", "We offer a few need-based scholarships to international students")이며 합격 후 신규 지원 불가. 모든 학생 100% need 충족("we meet 100% of demonstrated need for every student"). 대출은 소액 포함("We keep loans small and work-study manageable").', 'https://www.carleton.edu/admissions/apply/steps/international/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (72, 'Harvey Mudd College', '하비 머드 칼리지', 10, 1, 1500, 1560, '석차 제출 신입생 중 95%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출 비율 18%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor)·GPA·추천서 3가지이며, 에세이·교외활동·인성은 ''Important'', 표준화 시험·석차·재능은 ''Considered'', 지원자의 관심도는 ''Not Considered''입니다. 입학처는 학생들이 "embrace challenges, collaborate with one another, and ask for support when they need it" 하기를 기대한다고 공식 명시합니다.', 'https://www.hmc.edu/admission/apply/first-year-students/', 'test-optional', '캘리포니아주 클레어몬트에 위치한 소규모 사립 STEM 특화 리버럴 아츠 칼리지로, 클레어몬트 칼리지 연합(5C)의 일원입니다.', '로스앤젤레스 도심에서 동쪽으로 약 55km 떨어진 소도시 클레어몬트에 있으며, 연중 온화하고 건조한 남부 캘리포니아 기후입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.hmc.edu/admission/apply/first-year-students/', '2026-08-22', ARRAY['rigor','gpa','recommendations']::text[], 'https://www.hmc.edu/institutional-research/wp-content/uploads/sites/42/2026/03/CDS-HMC-2025.2026_shared.pdf', 'lac', 10, 'A small private STEM-focused liberal arts college in Claremont, California, and a member of the Claremont Colleges consortium.', 'In CDS 2025-26 C7, the three factors officially marked ''Very Important'' are rigor of secondary school record, GPA and recommendations; essay, extracurricular activities and character/personal qualities are ''Important'', standardized tests, class rank and talent/ability are ''Considered'', and level of applicant''s interest is ''Not Considered''. The admissions office officially states that it seeks students who "embrace challenges, collaborate with one another, and ask for support when they need it."', 'Located in the small city of Claremont, about 35 miles east of downtown Los Angeles, with a mild, dry Southern California climate year-round.', '95% of enrolled first-years who submitted class rank were in the top tenth of their high school class (CDS 2025-26 C10; 18% submitted rank)', 38, 32564, '2024-25', false, NULL, true, false, '공식: 국제학생은 need-aware("Because funding for international students is limited, your level of financial need may affect your chances for admission if you apply for financial aid"). 국제학생 need 100% 충족은 극소수만 가능("We are able to meet 100% of a family''s demonstrated need for only a handful of international students") → meets_full_need_intl false. 국제학생도 일부 merit award 지원 가능하며 So Scholarship은 국제학생 전용. CDS 2025-26 H6: need-based·non-need-based 모두 ''제공''으로 체크. 대출은 패키지에 포함(CDS H1 학생대출, Private alternative loans).', 'https://www.hmc.edu/admission/apply/international-applicants/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (73, 'Barnard College', '바너드 칼리지', 13, 2, 1480, 1540, '석차 제출 신입생 중 96%가 고교 상위 10% (CDS 2025-26 C10)', NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor)·GPA·에세이·추천서·인성(character) 5가지이며, 석차·교외활동·재능·봉사·근로 경험은 ''Important'', 표준화 시험과 지원자의 관심도는 ''Considered''입니다. 입학처는 지원서를 "contextually and holistically" 읽는다고 공식 명시합니다.', 'https://barnard.edu/admissions/the-application-process', 'test-optional', '뉴욕시 맨해튼에 위치한 사립 여자 리버럴 아츠 칼리지로, 컬럼비아 대학교와 제휴되어 있습니다.', '맨해튼 어퍼웨스트사이드(모닝사이드 하이츠)의 대도시 한복판에 있으며, 사계절이 뚜렷하고 겨울이 추운 미국 북동부 기후입니다.', true, false, false, false, '11월 초', NULL, NULL, '1월 초', 'https://barnard.edu/admissions/application-rounds', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations','character']::text[], 'https://barnard.edu/institutional-effectiveness/common-data-set', 'lac', 13, 'A private women''s liberal arts college in Manhattan, New York City, affiliated with Columbia University.', 'In CDS 2025-26 C7, the five factors officially marked ''Very Important'' are rigor of secondary school record, GPA, essay, recommendations and character/personal qualities; class rank, extracurricular activities, talent/ability, volunteer work and work experience are ''Important'', and standardized tests and level of applicant''s interest are ''Considered''. The admissions office officially states that it reads applications "contextually and holistically."', 'Located in the heart of a major city, in Manhattan''s Morningside Heights on the Upper West Side, with a four-season Northeastern climate and cold winters.', '96% of enrolled first-years who submitted class rank were in the top tenth of their high school class (CDS 2025-26 C10)', 31, 80574, '2025-26', true, NULL, true, false, '공식: merit 장학금 없음("Barnard gives no merit scholarships"). 국제학생(비시민·비영주권자)은 need-aware("We are need-aware for non-U.S. citizens and non-permanent residents"), 입학 학년당 소수의 need-based 장학금만 지원. 합격자는 100% need 충족("Barnard will meet 100% of the financial need of admitted students"). 아이드 패키지는 grant·loan·job 조합(대출 포함).', 'https://barnard.edu/admissions/internationalstudents') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (74, 'Davidson College', '데이비슨 칼리지', 13, 2, 1410, 1500, '석차 제출 신입생 중 80%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 13.2%), GPA 제출자 평균 3.85 (C12)', NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(Rigor of secondary school record), 추천서(Recommendations), 인성·개인 자질(Character/personal qualities)입니다. 입학처는 ''We seek evidence of academic success and well-developed interests.''라고 공식 명시합니다.', 'https://www.davidson.edu/admission-and-financial-aid/apply/first-year-applicants', 'test-optional', '노스캐롤라이나주 데이비슨에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '샬럿(Charlotte) 도심에서 북쪽으로 약 20마일(약 30km) 떨어진 소도시로, 겨울이 온화하고 여름이 덥고 습한 기후입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 중순', 'https://www.davidson.edu/admission-and-financial-aid/apply', '2026-08-22', ARRAY['rigor','recommendations','character']::text[], 'https://www.davidson.edu/media/9718/download', 'lac', 13, 'A small private liberal arts college located in Davidson, North Carolina.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, recommendations, and character/personal qualities. The admission office officially states: ''We seek evidence of academic success and well-developed interests.''', 'A small town about 20 miles (30 km) north of downtown Charlotte, with mild winters and hot, humid summers.', '80% of first-years who submitted class rank were in the top 10% of their class (CDS 2025-26 C10; 13.2% submitted rank); average GPA of submitters 3.85 (C12)', 201, 60298, '2025-26', true, 'Davidson의 비(非)니드 기반 장학금은 국제학생 포함 신입 지원자 전원이 고려 대상 (공식 명시; 개별 장학금 명칭은 미확인)', true, true, '공식: ''First-year applicants, including both domestic and international students, can be considered for Davidson''s non-need-based scholarships.'' 재정지원 패키지에 대출 미포함(The Davidson Trust).', 'https://www.davidson.edu/admission-and-financial-aid/financial-aid/policies-resources') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (75, 'Grinnell College', '그리넬 칼리지', 13, 2, 1430, 1520, '석차 제출 신입생 중 56.2%가 고교 상위 10% (CDS 2024-25 C10; 석차 제출률은 미보고)', NULL, false, true, ARRAY[]::text[], 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(Rigor of secondary school record), 석차(Class rank), 추천서(Recommendations)입니다. 입학처는 ''Admission to Grinnell is highly selective''이며 ''no single factor guarantees admission''이라고 공식 명시합니다.', 'https://www.grinnell.edu/admission/apply/first-year', 'test-optional', '아이오와주 그리넬에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '인구 약 9천 명의 소도시로 디모인(Des Moines)에서 동쪽으로 약 55마일(약 90km) 거리이며, 대륙성 기후로 겨울이 춥고 눈이 많습니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 중순', 'https://www.grinnell.edu/admission/apply/first-year/requirements', '2026-08-22', ARRAY['rigor','class_rank','recommendations']::text[], 'https://www.grinnell.edu/doc/grinnell-college-common-data-set-2024-2025', 'lac', 13, 'A small private liberal arts college located in Grinnell, Iowa.', 'Items officially marked ''Very Important'' in CDS 2024-25 C7 are rigor of secondary school record, class rank, and recommendations. The admission office officially states that ''Admission to Grinnell is highly selective'' and ''no single factor guarantees admission.''', 'A small town of about 9,000 people roughly 55 miles (90 km) east of Des Moines, with a continental climate of cold, snowy winters.', '56.2% of first-years who submitted class rank were in the top 10% of their class (CDS 2024-25 C10; share submitting rank not reported)', 243, 56853, '2024-25', true, '국제학생도 메리트 장학금 고려 대상 (공식: ''Outstanding international applicants may be considered for merit scholarships, regardless of their financial need profile''; 개별 명칭·금액은 공식 페이지에서 미확인)', true, true, '국제학생 니드 충족은 ''a combination of grants and student employment''(대출 미포함). 공식: ''Grinnell College has a need-aware admission policy for international students''.', 'https://www.grinnell.edu/admission/financial-aid/apply-aid/prospective-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (76, 'Hamilton College', '해밀턴 칼리지', 13, 2, 1440, 1510, '석차 제출 신입생 중 86.4%가 고교 상위 10% (CDS 2025-26 C10; 석차 제출률 18.4%)', NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(Rigor of secondary school record), 석차(Class rank), 학업 GPA(Academic GPA)입니다. 입학처는 ''Hamilton does not require the SAT or ACT''이며 ''All candidates are given full consideration, regardless of whether they include scores.''라고 공식 명시합니다.', 'https://www.hamilton.edu/admission/apply/testing', 'test-optional', '뉴욕주 클린턴에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '유티카(Utica) 인근의 작은 마을로 시러큐스에서 약 1시간, 뉴욕시에서 북서쪽으로 약 250마일(약 400km) 거리이며 겨울이 길고 눈이 많은 기후입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.hamilton.edu/admission/apply', '2026-08-22', ARRAY['rigor','class_rank','gpa']::text[], 'https://www.hamilton.edu/documents/CDS%202025-26%20Excel%20Final.pdf', 'lac', 13, 'A small private liberal arts college located in Clinton, New York.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, class rank, and academic GPA. The admission office officially states that ''Hamilton does not require the SAT or ACT'' and ''All candidates are given full consideration, regardless of whether they include scores.''', 'A small village near Utica, about an hour from Syracuse and roughly 250 miles (400 km) northwest of New York City, with long, snowy winters.', '86.4% of first-years who submitted class rank were in the top 10% of their class (CDS 2025-26 C10; 18.4% submitted rank)', 71, 74400, '2025-26', true, NULL, true, false, '메리트 장학금 없음 (공식 FAQ: ''Hamilton discontinued offering merit scholarships with the class that entered in the Fall of 2008''). 니드 기반 패키지에 소액 대출 포함(1학년 최대 $3,500).', 'https://www.hamilton.edu/admission/finaid/international') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (77, 'Middlebury College', '미들버리 칼리지', 13, 2, 1460, 1530, NULL, NULL, false, true, ARRAY[]::text[], 'CDS 2025-26(Fall 2025 Preliminary) C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(Rigor), 석차(Class rank), 학업 GPA, 교외 활동(Extracurricular activities), 재능(Talent/ability), 인성·개인 자질(Character/personal qualities)입니다. 입학처는 ''Middlebury is test optional''이라고 명시하며, 국제학생 심사는 ''need aware''라고 공식 명시합니다.', 'https://www.middlebury.edu/college/admissions/application-instructions-and-deadlines', 'test-optional', '버몬트주 미들버리에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '인구 약 9천 명의 소도시로 벌링턴(Burlington)에서 남쪽으로 약 35마일(약 55km), 보스턴에서 차로 약 3.5시간 거리이며 겨울이 길고 추운 기후입니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://www.middlebury.edu/admissions/apply/deadlines', '2026-08-22', ARRAY['rigor','class_rank','gpa','extracurricular','talent','character']::text[], 'https://www.middlebury.edu/sites/default/files/2026-02/Fall%202025%20CDS%20Preliminary.pdf', 'lac', 13, 'A small private liberal arts college located in Middlebury, Vermont.', 'Items officially marked ''Very Important'' in the CDS 2025-26 (Fall 2025 Preliminary) C7 are rigor of secondary school record, class rank, academic GPA, extracurricular activities, talent/ability, and character/personal qualities. The admission office states ''Middlebury is test optional'' and that international admission is ''need aware''.', 'A small town of about 9,000 people roughly 35 miles (55 km) south of Burlington and about 3.5 hours by car from Boston, with long, cold winters.', NULL, 192, 79468, '2024-25', true, NULL, true, false, '메리트 장학금 없음 (공식: ''All of Middlebury''s financial aid is need based. We don''t offer merit aid''). 국제학생 니드는 ''a combination of work, loans, and grants''로 충족.', 'https://www.middlebury.edu/office-student-financial-services/common-questions') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (78, 'Smith College', '스미스 칼리지', 13, 2, 1450, 1520, '석차 제출 신입생 중 79%가 고교 상위 10% (CDS 2024-25 C10; 석차 제출률 37%)', NULL, NULL, true, ARRAY[]::text[], 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(Rigor), 학업 GPA, 에세이(Application Essay), 추천서(Recommendations), 인성·개인 자질(Character/personal qualities)입니다. 입학처는 ''Your academic record, extracurricular activities, essay, recommendation letters, personal accomplishments and characteristics, and engagement in your community are all carefully considered.''라고 공식 명시합니다.', 'https://www.smith.edu/admission-aid/apply-smith/first-year-applicants', 'test-optional', '매사추세츠주 노샘프턴에 위치한 소규모 사립 여자 리버럴 아츠 칼리지입니다.', '인구 약 3만 명의 대학 도시로 보스턴에서 서쪽으로 약 100마일(약 160km), 뉴욕시에서 차로 약 3시간 거리이며 사계절이 뚜렷하고 겨울이 추운 기후입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 중순', 'https://www.smith.edu/admission-aid/apply-smith/first-year-applicants', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations','character']::text[], 'https://www1.smith.edu/sites/default/files/2025-02/2024-2025-CDS-Smith-PUB19Dec24%20v2.pdf', 'lac', 13, 'A small private women''s liberal arts college located in Northampton, Massachusetts.', 'Items officially marked ''Very Important'' in CDS 2024-25 C7 are rigor of secondary school record, academic GPA, application essay, recommendations, and character/personal qualities. The admission office officially states: ''Your academic record, extracurricular activities, essay, recommendation letters, personal accomplishments and characteristics, and engagement in your community are all carefully considered.''', 'A college town of about 30,000 people roughly 100 miles (160 km) west of Boston and about 3 hours by car from New York City, with four distinct seasons and cold winters.', '79% of first-years who submitted class rank were in the top 10% of their class (CDS 2024-25 C10; 37% submitted rank)', 164, 83285, '2024-25', true, '소수의 메리트 장학금 운영, 전 지원자 자동 고려 (공식: ''Smith College offers a limited number of awards based on merit rather than need. All applicants for admission are automatically considered''; 개별 명칭은 미확인)', true, true, '공식: ''Smith has eliminated loans from its undergraduate financial aid packages for those students receiving institutional need-based aid, replacing those funds with institutional grants.'' 국제학생은 입학 전 마감 내 재정지원 신청 필수(미신청 시 이후 영구 불가).', 'https://www.smith.edu/admission-aid/tuition-aid-applicants/international-applicants') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (79, 'Vassar College', '배서 칼리지', 13, 2, 1460, 1520, '석차 제출 신입생 중 79%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 29%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 학업 GPA, 에세이, 추천서, 과외활동, 재능/능력, 인성/개인 자질입니다. 입학처는 입학 심사에서 "Academic performance, as demonstrated in high school"과 "Personal strengths, motivation, and potential as evidenced in essays, recommendations, and community involvement"를 본다고 공식 명시합니다.', 'https://www.vassar.edu/admission/apply/how-to-apply/', 'test-optional', '뉴욕주 포킵시(Poughkeepsie)에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '허드슨강 변의 중소도시로 뉴욕시에서 북쪽으로 약 120km(기차 약 1시간 40분) 거리이며, 사계절이 뚜렷하고 겨울은 춥고 눈이 옵니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.vassar.edu/admission/apply/requirements/', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations','extracurricular','talent','character']::text[], 'https://offices.vassar.edu/institutional-research/wp-content/uploads/sites/23/2026/03/Vassar_College_CDS_2025-2026.pdf', 'lac', 13, 'A small private liberal arts college located in Poughkeepsie, New York.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, application essay, recommendations, extracurricular activities, talent/ability, and character/personal qualities. The admission office officially states that it weighs "Academic performance, as demonstrated in high school" and "Personal strengths, motivation, and potential as evidenced in essays, recommendations, and community involvement."', 'A mid-sized city on the Hudson River about 120 km (roughly 1 hr 40 min by train) north of New York City; four distinct seasons with cold, snowy winters.', '79% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 29% submitted rank)', 57, 88709, '2024-25', true, NULL, true, NULL, '재정지원은 전적으로 니드 기반("Financial aid is awarded exclusively on the basis of need")이며 메리트 장학금은 없습니다. 국제학생은 입학 지원과 동시에 재정지원을 신청해야 하며, 입학처는 국제학생 심사에서 need-aware입니다.', 'https://www.vassar.edu/admission/financial-aid/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (80, 'Wesleyan University', '웨슬리언 대학교', 13, 2, 1350, 1510, '석차 제출 신입생 중 73%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 18%)', NULL, NULL, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor) 하나뿐이며, 학급 석차·GPA·에세이·추천서·재능·인성 등은 ''Important''입니다. 입학처는 "We''re looking for intellectual risk-takers who possess the ability to succeed in a broad, rigorous academic environment"라고 공식 명시합니다.', 'https://www.wesleyan.edu/admission/application-process.html', 'test-optional', '코네티컷주 미들타운에 위치한 소규모 사립 리버럴 아츠 대학(명칭은 University이나 US News LAC 분류)입니다.', '코네티컷강 변의 소도시(인구 약 4만 7천)로 하트퍼드에서 남쪽 약 25km, 뉴욕시·보스턴에서 각각 차로 약 2시간 거리이며 겨울은 춥고 눈이 옵니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.wesleyan.edu/admission/application-process.html', '2026-08-22', ARRAY['rigor']::text[], 'https://www.wesleyan.edu/ir/common-data-sets.html', 'lac', 13, 'A small private liberal arts institution in Middletown, Connecticut (named a University but ranked by US News as a liberal arts college).', 'The only item officially marked ''Very Important'' in CDS 2025-26 C7 is rigor of secondary school record; class rank, GPA, essay, recommendations, talent and character are marked ''Important''. The admission office officially states: "We''re looking for intellectual risk-takers who possess the ability to succeed in a broad, rigorous academic environment."', 'A small city (about 47,000) on the Connecticut River, about 25 km south of Hartford and roughly 2 hours by car from both New York City and Boston; cold, snowy winters.', '73% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 18% submitted rank)', 91, 96349, '2025-26', true, NULL, true, true, '"We do not include loans in our undergraduate financial aid packages." 국제학생은 입학 지원 시점에 반드시 재정지원을 신청해야 하며(미신청 시 4년 내내 지원 불가), 한국 등 11개 아시아 국가 시민권자인 재정지원 신청자는 Freeman Asian Scholarship Program(4년 전액 장학) 심사 대상. 단, "admission for international students seeking financial aid is extremely competitive"라고 명시.', 'https://www.wesleyan.edu/admission/affordability-and-aid/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (81, 'Washington and Lee University', '워싱턴 앤드 리 대학교', 21, 2, 1430, 1530, '석차 제출 신입생 중 85%가 고교 상위 10% (CDS 2025-26 C10, 석차 제출률 31%)', NULL, true, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 추천서, 과외활동, 인성/개인 자질이며, 지원자의 관심도(demonstrated interest)는 ''Considered''입니다. 입학처는 ''whole-person'' 심사를 강조하며 지원자가 "choose to take high-level courses within the selection available"하는지, 즉 주어진 환경에서 스스로를 얼마나 도전시키는지를 본다고 공식 명시합니다.', 'https://www.wlu.edu/admissions/apply', 'test-optional', '버지니아주 렉싱턴에 위치한 소규모 사립 리버럴 아츠 대학교입니다.', '셰넌도어 밸리의 소도시(인구 약 7천)로 워싱턴 D.C.에서 차로 약 3시간, 리치먼드에서 약 2시간 거리이며 사계절이 온화한 편입니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://www.wlu.edu/admissions/apply', '2026-08-22', ARRAY['rigor','recommendations','extracurricular','character']::text[], 'https://my.wlu.edu/document/2025-common-data-set', 'lac', 21, 'A small private liberal arts university located in Lexington, Virginia.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, recommendations, extracurricular activities, and character/personal qualities; level of applicant''s interest is ''Considered''. The admission office emphasizes ''whole-person'' review and officially states that it looks at whether applicants "choose to take high-level courses within the selection available" to them.', 'A small town (about 7,000) in the Shenandoah Valley, roughly 3 hours by car from Washington, D.C. and about 2 hours from Richmond; relatively mild four-season climate.', '85% of enrolled first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10; 31% submitted rank)', 160, 90617, '2025-26', true, NULL, true, true, '"W&L admits students without considering their ability to pay" — 국내·국제·미등록 학생 모두 need-blind. "W&L meets the full demonstrated financial need of every admitted applicant entirely through grants and student employment, without loans." 메리트는 Johnson Scholarship(최대 44명, 등록금+기숙사비+식비 전액)으로 일원화되며 국제학생도 지원 가능. W&L Promise: 가구소득 20만 달러 미만이면 최소 등록금 전액 그랜트. 단, 국제학생 페이지에 "Admission to Washington and Lee does not guarantee financial assistance" 문구 있음.', 'https://www.wlu.edu/admissions/financial-aid') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (82, 'Colgate University', '콜게이트 대학교', 22, 2, 1450, 1510, '석차 제출 신입생 중 79%가 고교 상위 10%, GPA 제출자 평균 3.85 (CDS 2025-26 C10·C12, 석차 제출률 17%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor), 학급 석차, 학업 GPA이며 표준화 시험·에세이·추천서·과외활동·재능·인성은 ''Important''입니다. 입학처는 "Colgate seeks students who bring both intellect and unique talents to the overall student body"라며 "curiosity, commitment, empathy for others, and a vibrant excitement for intellectual exploration"을 본다고 공식 명시합니다.', 'https://www.colgate.edu/admission-aid/apply', 'test-optional', '뉴욕주 해밀턴에 위치한 소규모 사립 리버럴 아츠 대학교입니다.', '뉴욕주 중부의 시골 마을(인구 약 4천)로 시러큐스에서 차로 약 1시간, 뉴욕시에서 약 4시간 거리이며 겨울이 길고 눈이 많습니다.', true, true, false, false, '11월 초', '1월 중순', NULL, '1월 중순', 'https://www.colgate.edu/admission-aid/apply/first-year-applicants', '2026-08-22', ARRAY['rigor','class_rank','gpa']::text[], 'https://www.colgate.edu/sites/default/files/2026-07/CDS-PDF-2025-2026.pdf', 'lac', 22, 'A small private liberal arts university located in Hamilton, New York.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, class rank, and academic GPA; test scores, essay, recommendations, extracurriculars, talent and character are ''Important''. The admission office officially states that "Colgate seeks students who bring both intellect and unique talents to the overall student body" and looks for "curiosity, commitment, empathy for others, and a vibrant excitement for intellectual exploration."', 'A rural village (about 4,000) in central New York, roughly 1 hour by car from Syracuse and about 4 hours from New York City; long, snowy winters.', '79% of enrolled first-years who submitted class rank were in the top 10%; average high school GPA 3.85 among those submitting GPA (CDS 2025-26 C10/C12; 17% submitted rank)', 119, 86649, '2024-25', true, NULL, true, NULL, '"Colgate does not offer academic merit scholarships" — 전액 니드 기반. 국제학생 페이지: "We consider financial need during the review process for all applicants"(need-aware), "Colgate meets 100% of demonstrated financial need for every admitted student." Colgate Commitment(가구소득 30만 달러 이하 대상)는 미국 시민권자·영주권자 한정이며 국제학생 패키지의 대출 포함 여부는 공식 페이지에서 확인되지 않음.', 'https://www.colgate.edu/admission-aid/apply/international-applicants') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (83, 'University of Richmond', '리치먼드 대학교', 22, 2, 1420, 1490, '석차 제출 신입생 중 63%가 고교 상위 10%, GPA 제출자 평균 3.81 (CDS 2025-26 C10·C12, 석차 제출률 20%)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 난이도(rigor)와 학업 GPA이며 학급 석차·표준화 시험·에세이·추천서·과외활동·재능·인성은 ''Important''입니다. 입학처는 "well-rounded and dynamic students who are academically accomplished and multi-dimensional"을 찾으며 "we are using the whole application to consider the whole applicant"라고 공식 명시합니다.', 'https://admission.richmond.edu/process/index.html', 'test-optional', '버지니아주 리치먼드 교외에 위치한 소규모 사립 리버럴 아츠 대학교(경영대학 포함)입니다.', '버지니아주 주도 리치먼드(인구 약 23만) 서쪽 교외의 호수 캠퍼스로 워싱턴 D.C.에서 차로 약 2시간 거리이며, 여름은 덥고 습하고 겨울은 비교적 온화합니다.', true, true, true, false, '11월 초', '1월 초', '11월 초', '1월 초', 'https://admission.richmond.edu/process/early-decision.html', '2026-08-22', ARRAY['rigor','gpa']::text[], 'https://ifx.richmond.edu/pdfs/CDS2025-2026SectionC.pdf', 'lac', 22, 'A small private liberal arts university (with a business school) located in suburban Richmond, Virginia.', 'Items officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record and academic GPA; class rank, test scores, essay, recommendations, extracurriculars, talent and character are ''Important''. The admission office officially states that it seeks "well-rounded and dynamic students who are academically accomplished and multi-dimensional" and that "we are using the whole application to consider the whole applicant."', 'A lakeside suburban campus on the west side of Richmond (about 230,000), Virginia''s capital, roughly 2 hours by car from Washington, D.C.; hot, humid summers and relatively mild winters.', '63% of enrolled first-years who submitted class rank were in the top 10%; average high school GPA 3.81 among those submitting GPA (CDS 2025-26 C10/C12; 20% submitted rank)', 187, 67911, '2025-26', true, NULL, true, NULL, '"The University of Richmond is committed to meeting the full demonstrated financial need of all admitted domestic and international applicants." 국제학생은 need-aware 심사이며("the Office of Admission is need-aware when reviewing applications from non-U.S. citizens and non-U.S. permanent residents"), "International students... may receive full consideration for all merit-based scholarships, with the exception of the Army ROTC scholarship program" — Richmond Scholars는 12/1까지 지원 시 자동 심사. 국제학생은 Certification of Financial Responsibility 제출 필수.', 'https://financialaid.richmond.edu/applying/international.html') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (84, 'Bates College', '베이츠 칼리지', 24, 2, 1325, 1510, NULL, NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 엄격성(rigor)·석차·GPA·에세이·추천서·교외활동·재능·인성입니다. 지원자의 관심도(level of applicant''s interest)는 ''Important''로 표기되어 있습니다. 입학처는 "학업 준비도, 참여와 영향력, 베이츠에 대한 관심(academic preparation, involvement and impact, interest in Bates)을 기준으로 지원서를 종합 평가한다"고 공식 명시하며, 1984년부터 SAT/ACT 제출이 선택이라고 밝힙니다.', 'https://www.bates.edu/admission/frequently-asked-questions/', 'test-optional', '메인주 루이스턴에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '인구 약 3만 7천 명의 소도시로, 포틀랜드(메인)에서 북쪽으로 약 55km, 보스턴에서 차로 약 2시간 30분 거리이며 겨울이 길고 눈이 많습니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.bates.edu/admission/apply/application-options/', '2026-08-22', ARRAY['rigor','class_rank','gpa','essay','recommendations','extracurricular','talent','character']::text[], 'https://www.bates.edu/research/files/2026/06/CDS_2025-2026.pdf', 'lac', 24, 'A small private liberal arts college located in Lewiston, Maine.', 'In CDS 2025-26 C7, the items officially marked ''Very Important'' are rigor of secondary school record, class rank, academic GPA, application essay, recommendations, extracurricular activities, talent/ability, and character/personal qualities; level of applicant''s interest is marked ''Important''. The admission office officially states that it conducts a holistic review based on "academic preparation, involvement and impact, interest in Bates," and that submission of the SAT/ACT has been optional since 1984.', 'A small city of about 37,000 people, roughly 55 km north of Portland, Maine and about 2.5 hours by car from Boston, with long, snowy winters.', NULL, 106, 84952, '2024-25', true, NULL, true, NULL, '베이츠는 재정지원이 전액 need-based이며 국제학생 대상 merit 장학금을 제공하지 않는다고 공식 명시. 비미국시민 지원자에게는 대출 없이(grant+교내근로) 산정 필요액 100%를 충족하며, need-blind는 아님(need-aware)이라고 공식 명시.', 'https://www.bates.edu/financial-services/financial-aid/international-undergraduates/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (85, 'Colby College', '콜비 칼리지', 24, 2, 1450, 1540, NULL, NULL, false, NULL, ARRAY[]::text[], '콜비는 최근 Common Data Set을 공개하지 않아 C7 ''Very Important'' 항목을 확인할 수 없습니다. 입학처는 "심사는 정해진 공식 없이 종합적(holistic)으로 이뤄지며, 도전적인 과정에서 꾸준한 성취를 보여 주고 다양하고 협력적인 공동체에 의미 있게 기여할 지적으로 모험적인 학생을 찾는다"고 공식 명시합니다. 또한 테스트 옵셔널이며 인터뷰는 진행하지 않는다고 밝힙니다.', 'https://afa.colby.edu/apply/requirements/', 'test-optional', '메인주 워터빌에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '인구 약 1만 6천 명의 소도시로, 포틀랜드(메인)에서 차로 약 1시간 20분, 보스턴에서 약 3시간 거리이며 겨울이 길고 춥습니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://afa.colby.edu/apply/requirements/', '2026-08-22', ARRAY[]::text[], NULL, 'lac', 24, 'A small private liberal arts college located in Waterville, Maine.', 'Colby does not publish a recent Common Data Set, so C7 ''Very Important'' items cannot be verified. The admissions office officially states that its review is holistic with no set formula, and that it looks for "intellectually adventurous students who have demonstrated consistent achievement in a challenging program of study and who seem likely to make meaningful contributions to our diverse and collaborative community." It is test-optional and does not offer interviews.', 'A small town of about 16,000 people, roughly 1 hour 20 minutes by car from Portland, Maine and about 3 hours from Boston, with long, cold winters.', NULL, NULL, NULL, NULL, true, NULL, true, true, 'Colby Commitment: 모든 합격생(국제학생 포함)의 산정 필요액 100%를 대출 없이(grant+교내근로) 충족한다고 공식 명시. merit 장학금(학업·운동·기타 재능 기반)은 제공하지 않음(National Merit Finalist $2,000 인정 수당만). 입학 FAQ에서 ''Colby is need aware''라고 공식 명시.', 'https://afa.colby.edu/apply/applying-for-aid/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (86, 'Haverford College', '해버퍼드 칼리지', 24, 2, 1470, 1540, '석차 제출 신입생 중 94.1%가 고교 상위 10% (CDS 2024-25 C10)', NULL, NULL, true, ARRAY[]::text[], 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 엄격성(rigor)·GPA·에세이·추천서·교외활동·인성이며, 지원자의 관심도는 ''Considered''입니다. 입학처는 "입학 심사는 각 지원서를 각별한 주의와 개인적 관심으로 다루는 포괄적·종합적(holistic) 검토로 진행된다"고 공식 명시하며, 테스트 옵셔널이고 합격 후 등록 보증금을 받지 않는다고 밝힙니다.', 'https://www.haverford.edu/admission', 'test-optional', '펜실베이니아주 해버퍼드(필라델피아 교외)에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '필라델피아 서쪽 ''메인 라인'' 교외 주거지역에 있으며 도심까지 약 15km(통근열차 약 20-30분)이고, 사계절이 뚜렷하되 뉴잉글랜드보다 겨울이 온화한 편입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.haverford.edu/admission/applying/application-timeline', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations','extracurricular','character']::text[], 'https://www.haverford.edu/sites/default/files/Office/President/CDS_2024-2025.pdf', 'lac', 24, 'A small private liberal arts college located in Haverford, Pennsylvania, a suburb of Philadelphia.', 'In CDS 2024-25 C7, the items officially marked ''Very Important'' are rigor of secondary school record, academic GPA, application essay, recommendations, extracurricular activities, and character/personal qualities; level of applicant''s interest is ''Considered''. The admission office officially states that its "Admission process is conducted as a comprehensive, holistic review in which each application is treated with extraordinary care and personal attention," that it is test-optional, and that it requires no enrollment deposit.', 'Located in the Main Line suburbs west of Philadelphia, about 15 km (20-30 minutes by regional rail) from downtown, with four distinct seasons and milder winters than New England.', '94.1% of first-year students who submitted class rank were in the top 10% of their high school class (CDS 2024-25 C10)', 56, 87516, '2024-25', true, NULL, true, NULL, '모든 재정지원은 need-based(merit 없음). ''매년 제한된 수(limited number)의 국제학생에게 재정지원을 제공하며, 지원을 받는 학생은 산정 필요액 전액을 충족''한다고 공식 명시. 1학년 때 지원을 못 받은 국제학생은 이후 학년에도 지원 불가.', 'https://www.haverford.edu/financial-aid/international-applicants') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (87, 'College of the Holy Cross', '홀리크로스 칼리지', 27, 3, 1270, 1420, '석차 제출 신입생(전체의 22%) 중 38%가 고교 상위 10% (CDS 2023-24 C10)', NULL, NULL, true, ARRAY[]::text[], 'CDS 2023-24 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 엄격성(rigor)·GPA·추천서·에세이·인터뷰·인성이며, 지원자의 관심도는 ''Considered''입니다. 입학처는 "홀리크로스는 지원자를 전인적으로(whole person) 본다"며 "단일 시험 점수 대신 4년간의 학업 프로그램과 교실 밖 관심사에 초점을 맞춰 입학 결정을 내린다"고 공식 명시합니다(2006년 입학생부터 테스트 옵셔널).', 'https://www.holycross.edu/admissions-aid/apply', 'test-optional', '매사추세츠주 우스터에 위치한 소규모 사립(예수회) 리버럴 아츠 칼리지입니다.', '매사추세츠 제2의 도시(인구 약 20만)에 있으며 보스턴에서 서쪽으로 약 65km(차로 약 1시간, 통근열차 운행)이고 겨울에 눈이 많습니다.', true, true, false, false, '11월 중순', '1월 중순', NULL, '1월 중순', 'https://www.holycross.edu/admissions-aid/apply', '2026-08-22', ARRAY['rigor','gpa','recommendations','essay','interview','character']::text[], 'https://www.holycross.edu/document/common-data-set-20232024', 'lac', 27, 'A small private Jesuit liberal arts college located in Worcester, Massachusetts.', 'In CDS 2023-24 C7, the items officially marked ''Very Important'' are rigor of secondary school record, academic GPA, recommendations, application essay, interview, and character/personal qualities; level of applicant''s interest is ''Considered''. The admissions office officially states that "we care about who you are as a whole person" and that it "focuses on the four-year academic program and outside-the-classroom interests in our admission decisions — instead of on a single test score" (test-optional since the class entering fall 2006).', 'Located in Massachusetts'' second-largest city (about 200,000 people), roughly 65 km west of Boston (about 1 hour by car, commuter rail available), with snowy winters.', '38% of first-year students who submitted class rank (22% of the class) were in the top 10% of their high school class (CDS 2023-24 C10)', NULL, NULL, NULL, true, NULL, true, false, '''합격한 모든 국제학생의 산정 필요액 100%를 충족''한다고 재정지원 페이지에 공식 명시하되, 국제학생 페이지에는 ''국제학생용 재원은 제한적(limited funding)''이라고 명시. 소수의 merit 장학금이 있으나 국제학생 자격 여부는 미명시. 패키지에 연방·교내 대출 포함(no-loan 아님). 가구소득 $10만 이하(자산 보통)면 등록금 전액 grant.', 'https://www.holycross.edu/admissions-aid/tuition-financial-aid/financial-aid') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (88, 'Macalester College', '매칼레스터 칼리지', 28, 3, 1350, 1480, '석차 제출 신입생(전체의 26%) 중 53%가 고교 상위 10% (CDS 2025-26 C10)', NULL, false, NULL, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 과정의 엄격성(rigor)과 GPA이며, 에세이·추천서·교외활동·인성은 ''Important''입니다. 입학처는 "종합 심사(holistic review)를 실시하며 맥락 속의 학업 성취, 추천서, 에세이, 리더십 경험과 잠재력, 교외활동을 입학위원회가 면밀히 검토한다"고, 또 "가장 중요한 부분은 고교 내내 쌓아 온 학업 성취"라고 공식 명시합니다(테스트 옵셔널).', 'https://www.macalester.edu/admissions/us-admissions/first-year/', 'test-optional', '미네소타주 세인트폴에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '미니애폴리스-세인트폴 대도시권의 주거지역에 있어 세인트폴(인구 약 30만)·미니애폴리스 도심까지 각각 차로 15분 안팎이며, 겨울이 매우 춥고 깁니다.', true, true, true, false, '11월 초', '1월 초', '11월 초', '1월 중순', 'https://www.macalester.edu/admissions/deadlines/', '2026-08-22', ARRAY['rigor','gpa']::text[], 'https://www.macalester.edu/institutional-research/wp-content/uploads/sites/515/CDS_2025-2026_Macalester-College_completed-1.pdf', 'lac', 28, 'A small private liberal arts college located in Saint Paul, Minnesota.', 'In CDS 2025-26 C7, the items officially marked ''Very Important'' are rigor of secondary school record and academic GPA; essay, recommendations, extracurricular activities, and character are ''Important''. The admissions office officially states that it "practices holistic admission review" in which "academic performance in context, recommendation letters, essays, leadership experience and potential, and extracurricular involvement are thoroughly reviewed by the Admissions Committee," and that "the most important part of your application is ... your academic performance" (test-optional).', 'Set in a residential neighborhood of the Minneapolis-Saint Paul metro area, about 15 minutes by car from both downtown Saint Paul (about 300,000 people) and downtown Minneapolis, with very cold, long winters.', '53% of first-year students who submitted class rank (26% of the class) were in the top 10% of their high school class (CDS 2025-26 C10)', 287, 59839, '2024-25', true, NULL, true, false, '국제학생 FAQ에서 ''재정 필요도(financial need)가 입학 결정에 역할을 한다''(need-aware)고, 동시에 ''등록하는 모든 학생의 산정 필요액 전액 충족''을 공식 명시. 국제학생 대상 merit: Charles J. Turck Presidential Honor Scholarship(연 $15,000-35,000, 자동 심사). 지원 의사는 지원 시점에 표시해야 하며 합격 후에는 지원 불가.', 'https://www.macalester.edu/admissions/international/faq/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (89, 'Mount Holyoke College', '마운트 홀리요크 칼리지', 29, 3, 1365, 1485, '석차 제출 신입생(전체의 33%) 중 49%가 고교 상위 10%, 79%가 상위 25%이며 GPA 제출자 평균 GPA는 3.88입니다 (CDS 2025-26 C10·C12).', 19.9, NULL, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 교과 난이도(rigor), 학업 GPA, 에세이, 추천서이며 석차·인터뷰·과외활동·재능·인성은 ''Important''입니다. 입학처는 "Who you are as a person and your potential as a Mount Holyoke student matters to us much more than a series of numbers"라고 공식 명시하며, 폭넓은 호기심·열린 태도·긍정적 영향을 주려는 의지를 본다고 밝힙니다.', 'https://www.mtholyoke.edu/admission/apply-undergraduate-first-year', 'test-optional', '매사추세츠주 사우스해들리에 위치한 소규모 사립 여자 리버럴 아츠 칼리지(세븐 시스터즈)입니다.', '보스턴에서 서쪽으로 약 145km 떨어진 파이오니어 밸리의 소도시에 있으며, 겨울이 길고 눈이 많은 뉴잉글랜드 기후입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 중순', 'https://www.mtholyoke.edu/admission/apply-undergraduate-first-year/application-deadlines-undergraduates', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations']::text[], 'https://drive.google.com/file/d/1YBj1g21DRKEMSV0WHaiIT6paJg1qruX9/view', 'lac', 29, 'A small private women''s liberal arts college (one of the Seven Sisters) in South Hadley, Massachusetts.', 'In CDS 2025-26 C7 the factors officially marked ''Very Important'' are rigor of secondary school record, academic GPA, application essay and recommendations; class rank, interview, extracurricular activities, talent/ability and character are ''Important''. The admission office officially states: "Who you are as a person and your potential as a Mount Holyoke student matters to us much more than a series of numbers," and says it looks for wide-ranging curiosity, open-mindedness and a desire to make a positive impact.', 'Located in a small town in the Pioneer Valley about 145 km west of Boston; New England climate with long, snowy winters.', 'Of first-years who submitted class rank (33% of the class), 49% were in the top tenth and 79% in the top quarter; average reported high school GPA 3.88 (CDS 2025-26 C10, C12).', 257, 53460, '2025-26', true, '별도 명칭 없이 모든 지원자 자동 심사 ("All applicants to Mount Holyoke College are automatically considered for merit aid"; 평균 메리트 장학금 USD 17,500)', true, false, '공식 국제학생 페이지: 신입 국제학생의 45%가 need-based 장학금(평균 USD 58,686) 또는 메리트 장학금을 받음. 국제학생 need-based 패키지는 그랜트+고정금리 학자금 대출+교내 근로로 구성되며 대출 부분이 매년 최소 $1,000씩 증가한다고 명시.', 'https://www.mtholyoke.edu/admission/apply-undergraduate-first-year/application-process/international-admission') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (90, 'Bryn Mawr College', '브린 마 칼리지', 30, 3, 1300, 1470, '석차 제출 신입생(전체의 21%) 중 67%가 고교 상위 10%, 93%가 상위 25%입니다 (CDS 2025-26 C10; C11·C12 GPA 분포는 미보고).', 9.5, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 교과 난이도(rigor), 석차, 에세이, 추천서이며 GPA·인터뷰·과외활동·인성은 ''Important'', 지원자의 관심도(demonstrated interest)는 ''Not Considered''입니다. 입학처는 "We know that you are more than just what you do in the classroom, so we use a holistic review process to get to know the whole you when reading your application"이라고 공식 명시합니다.', 'https://www.brynmawr.edu/admissions-aid/apply/first-year-students', 'test-optional', '펜실베이니아주 필라델피아 교외 브린 마에 위치한 소규모 사립 여자 리버럴 아츠 칼리지(세븐 시스터즈, 하버포드·스와스모어와 학점 교류)입니다.', '필라델피아 도심에서 약 18km 떨어진 메인라인 교외로 통근열차로 30분 내외이며, 사계절이 뚜렷하고 겨울은 비교적 온화한 편입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 중순', 'https://www.brynmawr.edu/admissions-aid/apply/first-year-students', '2026-08-22', ARRAY['rigor','class_rank','essay','recommendations']::text[], 'https://www.brynmawr.edu/sites/default/files/media/documents/2026-04/CDS%202025-26%20Bryn%20Mawr%20Read%20Only.pdf', 'lac', 30, 'A small private women''s liberal arts college (one of the Seven Sisters, cross-registration with Haverford and Swarthmore) in Bryn Mawr, a suburb of Philadelphia, Pennsylvania.', 'In CDS 2025-26 C7 the factors officially marked ''Very Important'' are rigor of secondary school record, class rank, application essay and recommendations; GPA, interview, extracurricular activities and character are ''Important'', and level of applicant''s interest is ''Not Considered''. The admission office officially states: "We know that you are more than just what you do in the classroom, so we use a holistic review process to get to know the whole you when reading your application."', 'On Philadelphia''s Main Line suburbs about 18 km from downtown (roughly 30 minutes by regional rail); four distinct seasons with relatively mild winters.', 'Of first-years who submitted class rank (21% of the class), 67% were in the top tenth and 93% in the top quarter (CDS 2025-26 C10; GPA distribution in C11-C12 not reported).', 110, 80407, '2025-26', true, NULL, true, false, '공식 국제학생 페이지: "International students are not eligible for merit aid." need-based 지원은 가능하나 "Bryn Mawr is a need-sensitive institution, meaning that while we meet the full calculated need of all admitted students, we have a limited amount of funds available"라고 명시. 입학 후 재정지원 신규 신청 불가(지원 시 신청 필수).', 'https://www.brynmawr.edu/admissions-aid/apply/international-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (91, 'Bucknell University', '버크넬 대학교', 30, 3, 1170, 1360, '석차 제출 신입생(전체의 18%) 중 56%가 고교 상위 10%, 85%가 상위 25%이며 평균 GPA는 3.58입니다 (CDS 2025-26 C10·C12).', 5.9, false, true, ARRAY['College of Arts & Sciences','College of Engineering','Freeman College of Management']::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 교과 난이도(rigor), 학업 GPA, 에세이, 과외활동, 재능/능력, 인성이며, 봉사·근로 경험은 ''Important'', 지원자의 관심도는 ''Considered''입니다. 입학처는 "Admission to Bucknell is based on more than the traditional data points like test scores and GPA — we seek students who are engaged in the world around them and passionately in pursuit of their own distinct purpose"라고 공식 명시합니다.', 'https://www.bucknell.edu/admissions-aid/apply-bucknell', 'test-optional', '펜실베이니아주 루이스버그에 위치한 사립 대학으로, 리버럴 아츠 중심에 공학·경영 단과대학을 함께 둔 학부 중심 대학입니다.', '펜실베이니아 중부의 소도시(인구 약 5천 명대)로 필라델피아·피츠버그에서 각각 약 3시간 거리이며, 사계절이 뚜렷하고 겨울에 눈이 내립니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://www.bucknell.edu/admissions-aid/admissions-dates-deadlines', '2026-08-22', ARRAY['rigor','gpa','essay','extracurricular','talent','character']::text[], 'https://www.bucknell.edu/sites/default/files/institutional-research/common_data_set_2025-26.pdf', 'lac', 30, 'A private, undergraduate-focused university in Lewisburg, Pennsylvania, combining a liberal arts core with separate colleges of Engineering and Management.', 'In CDS 2025-26 C7 the factors officially marked ''Very Important'' are rigor of secondary school record, academic GPA, application essay, extracurricular activities, talent/ability and character/personal qualities; volunteer work and work experience are ''Important'' and level of applicant''s interest is ''Considered''. The admission office officially states: "Admission to Bucknell is based on more than the traditional data points like test scores and GPA — we seek students who are engaged in the world around them and passionately in pursuit of their own distinct purpose."', 'A small town in central Pennsylvania, roughly three hours from both Philadelphia and Pittsburgh; four distinct seasons with snowy winters.', 'Of first-years who submitted class rank (18% of the class), 56% were in the top tenth and 85% in the top quarter; average high school GPA 3.58 (CDS 2025-26 C10, C12).', 130, 71387, '2025-26', false, '소수의 부분 메리트 장학금 ("A few partial merit scholarships are awarded to international students each year"; 개별 명칭은 국제학생 페이지에 미기재)', false, false, '공식 국제학생 재정지원 페이지: "Bucknell is currently not ''need-blind'' for international students", "Bucknell financial aid for international students is limited", "only a small number of highly qualified international applicants are ultimately chosen to receive financial assistance". 1학년에 지원 못 받으면 이후 학년에도 지원 없음. 메리트 프로그램(Presidential Fellowship $30,000, Dean''s Scholarship $20,000, Engineering/Management/Malesardi Merit Scholars $40,000 등)은 국제학생 자격이 명시되지 않음.', 'https://www.bucknell.edu/admissions-aid/tuition-fees-financial-aid/apply-financial-aid/financial-aid-international-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (92, 'Colorado College', '콜로라도 칼리지', 30, 3, 1240, 1430, '석차 제출 신입생(전체의 22.6%) 중 58.1%가 고교 상위 10%, 86.3%가 상위 25%이며 평균 GPA는 3.93입니다 (CDS 2025-26 C10·C12).', 6.9, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 표기한 항목은 없으며, 고교 교과 난이도(rigor)·학업 GPA·에세이·추천서·과외활동을 ''Important''로, 석차·표준화 시험·인터뷰·재능·인성·지원자의 관심도 등은 ''Considered''로 공식 표기했습니다. 입학처는 "Our holistic review process considers your academic work, writing, letters of recommendation, extracurricular activities, and personal qualities"라고 공식 명시하며, 제출된 시험 점수는 지원서를 강화할 때만 고려한다고 밝힙니다.', 'https://www.coloradocollege.edu/admission/apply/first-year-students.html', 'test-optional', '콜로라도주 콜로라도스프링스에 위치한 소규모 사립 리버럴 아츠 칼리지로, 한 번에 한 과목을 집중 이수하는 블록 플랜(Block Plan)으로 운영됩니다.', '덴버에서 남쪽으로 약 110km 떨어진 인구 약 50만 명의 중규모 도시로 로키산맥 기슭 해발 약 1,800m 고지대에 있으며, 맑고 건조하고 일교차가 크며 겨울에 눈이 옵니다.', true, true, true, false, '11월 초', '1월 중순', '11월 초', '1월 중순', 'https://www.coloradocollege.edu/admission/apply/first-year-students.html', '2026-08-22', ARRAY[]::text[], 'https://www.coloradocollege.edu/offices/ipe/documents/CDS-2025-2026_PDF_Final.pdf', 'lac', 30, 'A small private liberal arts college in Colorado Springs, Colorado, known for its Block Plan of taking one course at a time.', 'In CDS 2025-26 C7 no factor is marked ''Very Important''; rigor of secondary school record, academic GPA, application essay, recommendations and extracurricular activities are officially ''Important'', while class rank, standardized tests, interview, talent/ability, character and level of applicant''s interest are ''Considered''. The admission office officially states: "Our holistic review process considers your academic work, writing, letters of recommendation, extracurricular activities, and personal qualities," and says submitted test scores are considered only if they strengthen the application.', 'A mid-sized city (about 500,000 people) roughly 110 km south of Denver at ~1,800 m elevation at the foot of the Rockies; sunny, dry climate with large day-night temperature swings and snowy winters.', 'Of first-years who submitted class rank (22.6% of the class), 58.1% were in the top tenth and 86.3% in the top quarter; average high school GPA 3.93 (CDS 2025-26 C10, C12).', 73, 52713, '2025-26', true, 'Leadership Scholarship(4년 $60,000) 등 자동 메리트 심사("Our strongest applicants are automatically considered for merit aid"); 국제학생 자격은 공식 페이지에 명시되지 않음', true, false, '공식: "CC meets 100% of every student''s demonstrated financial need" / "Colorado College meets the full demonstrated need for all students". 국제학생 페이지: "International applicants seeking financial aid comprise our most competitive group of applicants each year", 수천 명 중 소수(a handful)만 전액 지원 가능. 재정지원 미신청 국제학생은 8학기 전액 자비 부담 능력 증명 필요. 입학 후 재정지원 신규 신청 불가.', 'https://www.coloradocollege.edu/admission/for-students/admission-requirements/international-students/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (93, 'Lafayette College', '라파예트 칼리지', 30, 3, 1360, 1490, '석차 제출 신입생(전체의 22%) 중 53%가 고교 상위 10%, 81%가 상위 25%이며 평균 GPA는 3.56입니다 (CDS 2025-26 C10·C12).', 7.3, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 고교 교과 난이도(rigor)와 학업 GPA이며, 석차·표준화 시험·에세이·추천서·인터뷰·과외활동·재능·인성·지원자의 관심도(demonstrated interest)는 ''Important''입니다. 입학처는 지원자의 학업 성취와 과목 난이도, 인터뷰, 동기·사회적 인식·리더십 잠재력 같은 인성을 본다고 밝히며 활동은 개수보다 "your top six activities"의 깊이를 중시한다고 공식 명시합니다.', 'https://admissions.lafayette.edu/apply/what-we-look-for/', 'test-optional', '펜실베이니아주 이스턴에 위치한 소규모 사립 리버럴 아츠 칼리지로, 리버럴 아츠 칼리지로는 드물게 ABET 인증 공학 학위 과정을 운영합니다.', '뉴욕시에서 약 110km, 필라델피아에서 약 100km 떨어진 리하이 밸리의 소도시(인구 약 3만 명)로, 사계절이 뚜렷하고 겨울에 눈이 내립니다.', true, true, false, false, '11월 초', '1월 초', NULL, '1월 초', 'https://admissions.lafayette.edu/apply/', '2026-08-22', ARRAY['rigor','gpa']::text[], 'https://oir.lafayette.edu/wp-content/uploads/sites/196/2026/01/CDS2025-2026.pdf', 'lac', 30, 'A small private liberal arts college in Easton, Pennsylvania, unusual among LACs for offering ABET-accredited engineering degrees.', 'In CDS 2025-26 C7 the factors officially marked ''Very Important'' are rigor of secondary school record and academic GPA; class rank, standardized tests, essay, recommendations, interview, extracurricular activities, talent/ability, character and level of applicant''s interest are ''Important''. The admission office says it weighs academic performance and course rigor, the interview, and personal character (motivation, social awareness, leadership potential), and officially states it focuses on the depth of "your top six activities" rather than the number of activities.', 'A small city (about 30,000 people) in the Lehigh Valley roughly 110 km from New York City and 100 km from Philadelphia; four distinct seasons with snowy winters.', 'Of first-years who submitted class rank (22% of the class), 53% were in the top tenth and 81% in the top quarter; average high school GPA 3.56 (CDS 2025-26 C10, C12).', 111, 64791, '2025-26', true, 'Marquis Fellowship(등록금 전액)·Marquis Scholarship(등록금 절반)·Cur Non Scholarship($17,500-31,500); 공식 국제학생 FAQ: "International students are eligible to receive merit scholarships"', true, false, '공식: "Lafayette is proud to be one of only a select few colleges in the United States to guarantee to meet full demonstrated financial need of all admitted students, both domestic and international." 단 "Lafayette College is need aware and considers a student''s financial situation when making admission decisions." 1학년에 재정지원을 못 받은 국제학생은 이후에도 지원 불가(예산 제약). 메리트 장학금은 별도 신청 없이 입학처가 결정.', 'https://admissions.lafayette.edu/apply/international-students/') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (94, 'Denison University', '데니슨 대학교', 34, 3, 1270, 1420, '석차 제출 신입생 중 45%가 고교 상위 10% (CDS 2025-26 C10)', NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 과정의 엄격성(rigor), 학업 GPA, 지원 에세이, 추천서입니다. 면접·교외 활동·재능은 ''Important'', 지원자의 관심도(demonstrated interest)와 표준화 시험 점수는 ''Considered''입니다. 입학처는 "학업 생활에 대한 진지함을 보여 주고, 그에 더해 다양한 관심사·특성·개인적 자질을 캠퍼스 공동체에 가져올 학생을 찾는다"라고 공식 명시하며, 시험 점수를 제출하지 않으면 고교 교과 과정의 엄격성과 이수 과목 성취도에 추가 비중을 둔다고 밝힙니다.', 'https://denison.edu/campus/admission/apply-for-admission', 'test-optional', '오하이오주 그랜빌에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '인구 약 6천 명의 작은 마을로 주도 콜럼버스에서 동쪽으로 약 45km(차로 35분) 거리이며, 사계절이 뚜렷하고 겨울에 눈이 많은 기후입니다.', true, true, false, false, '11월 중순', '1월 중순', NULL, '1월 중순', 'https://denison.edu/campus/admission/apply-for-admission', '2026-08-22', ARRAY['rigor','gpa','essay','recommendations']::text[], 'https://denison.edu/sites/default/files/forms/2026-08/cds_du_20252026_published_updated2026.08.14.pdf', 'lac', 34, 'A small private liberal arts college in Granville, Ohio.', 'Factors officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, application essay, and recommendations. Interview, extracurricular activities, and talent/ability are ''Important''; level of applicant''s interest and standardized test scores are ''Considered''. The admission office officially states it is "seeking students who have demonstrated a seriousness toward their academic life and who, in addition, would bring a variety of interests, characteristics, and personal qualities to our dynamic campus community," and that when no test scores are submitted, additional weight is placed on curriculum rigor and course performance.', 'A small village of about 6,000 people roughly 45 km (35 minutes by car) east of Columbus, the state capital; four distinct seasons with snowy winters.', '45% of first-years who submitted class rank were in the top 10% of their high school class (CDS 2025-26 C10).', 358, 55613, '2025-26', true, '국제학생도 내국인과 동일한 메리트 장학금 심사 대상 (연 $5,000~등록금 전액; 개별 장학금 명칭은 국제학생 재정지원 페이지에 미기재)', true, NULL, '공식 페이지: "International students are eligible for the same institutional need-based financial aid and merit-based scholarships as domestic students"; 메리트 장학금 범위 연 $5,000~full tuition. 단 "Denison is need-aware in the application process"(재정지원 필요 시 합격 경쟁 영향).', 'https://denison.edu/campus/admission/international-applicant-financial-aid') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (95, 'Franklin & Marshall College', '프랭클린 앤 마셜 칼리지', 35, 3, 1310, 1470, NULL, NULL, false, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 과정의 엄격성(rigor), 학급 석차, 학업 GPA, 인성·개인적 자질(character)입니다. 에세이·추천서·면접·교외 활동·재능·봉사활동은 ''Important'', 표준화 시험 점수와 지원자의 관심도(demonstrated interest)는 ''Considered''입니다. 입학처는 30년 넘게 test-optional을 유지해 왔으며 "SAT/ACT 점수 제출 여부는 지원자가 선택하고, 제출된 점수는 지원서를 강화할 때만 고려하는 ''no harm'' 방식"이라고 공식 명시합니다.', 'https://www.fandm.edu/apply/', 'test-optional', '펜실베이니아주 랭커스터에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '인구 약 6만 명의 소도시로 필라델피아에서 서쪽으로 약 110km(차로 1시간 30분) 거리이며, 사계절이 뚜렷하고 여름은 습하며 겨울에 눈이 내립니다.', true, true, false, false, '11월 중순', '1월 중순', NULL, '1월 중순', 'https://www.fandm.edu/apply/', '2026-08-22', ARRAY['rigor','class_rank','gpa','character']::text[], 'https://drive.google.com/file/d/1CpyIXEDF-2bMSlt8qXimtThANg0xsUlw/view', 'lac', 35, 'A small private liberal arts college in Lancaster, Pennsylvania.', 'Factors officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, class rank, academic GPA, and character/personal qualities. Essay, recommendations, interview, extracurricular activities, talent/ability, and volunteer work are ''Important''; standardized test scores and level of applicant''s interest are ''Considered''. The admission office officially states it has been test-optional for more than 30 years: "when you apply to F&M, you choose whether or not to submit your standardized test (SAT or ACT) scores," reviewed under a ''no harm'' approach.', 'A small city of about 60,000 roughly 110 km (1.5 hours by car) west of Philadelphia; four distinct seasons with humid summers and snowy winters.', NULL, 276, 56601, '2025-26', true, NULL, true, NULL, '국제학생 페이지: "If you''re admitted to F&M, we will meet 100% of your institutionally determined financial need for all four years" / "If you require a high level of aid, the admission process becomes more competitive"(need-aware). 재정지원 페이지에 ''Merit & Dedicated Scholarships (determined by the Office of Admission)'' 언급은 있으나 개별 명칭·국제학생 대상 여부는 미기재.', 'https://www.fandm.edu/apply/international-first-year-application-checklist.html') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (96, 'Occidental College', '옥시덴탈 칼리지', 35, 3, 1400, 1510, 'GPA 제출 신입생의 평균 고교 GPA 3.64(중간값 3.68), 석차 제출자 중 16%가 상위 10% (CDS 2025-26 C10·C12)', NULL, NULL, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 과정의 엄격성(rigor), 학업 GPA, 지원 에세이, 교외 활동입니다. 학급 석차·추천서·인성·봉사활동은 ''Important'', 표준화 시험 점수와 지원자의 관심도(demonstrated interest)는 ''Considered'', 동문 관계는 ''Not Considered''입니다. 입학처는 지원서를 "당신이 누구이고, 무엇에 호기심을 느끼며, 대학에서 어떻게 성장하고 싶은지를 나누는 기회"라고 설명하며 모든 지원 일정(ED/EA/RD)에 동일한 홀리스틱 심사를 적용한다고 공식 명시합니다.', 'https://www.oxy.edu/admission-aid/first-year/application-deadlines', 'test-optional', '캘리포니아주 로스앤젤레스(이글록 지역)에 위치한 소규모 사립 리버럴 아츠 칼리지입니다.', '미국 2위 대도시 로스앤젤레스 시내에 있으며 다운타운 LA에서 북동쪽으로 약 13km, 연중 온화하고 건조한 지중해성 기후입니다.', true, true, true, false, '11월 초', '1월 초', '11월 초', '1월 초', 'https://www.oxy.edu/admission-aid/first-year/application-deadlines', '2026-08-22', ARRAY['rigor','gpa','essay','extracurricular']::text[], 'https://www.oxy.edu/sites/default/files/assets/Institutional_Research/CDS_C_2526_0.pdf', 'lac', 35, 'A small private liberal arts college in the Eagle Rock neighborhood of Los Angeles, California.', 'Factors officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, application essay, and extracurricular activities. Class rank, recommendations, character/personal qualities, and volunteer work are ''Important''; standardized test scores and level of applicant''s interest are ''Considered''; alumni relation is ''Not Considered''. The admission office officially describes the application as "a chance to share who you are, what you''re curious about, and how you hope to grow in college," and states all timelines (ED/EA/RD) receive the same holistic review.', 'Inside the city of Los Angeles, about 13 km northeast of downtown LA; mild, dry Mediterranean climate year-round.', 'Average high school GPA 3.64 (median 3.68) among first-years who submitted GPA; 16% of those who submitted class rank were in the top 10% (CDS 2025-26 C10/C12).', 51, 36111, '2025-26', NULL, '모든 국제학생 지원자는 메리트 장학금 심사를 자동으로 받음 ("All international applicants are automatically considered for merit-based scholarships"; 개별 명칭 미기재)', true, NULL, '국제학생 페이지: "Need-based financial aid for international students is very limited and highly competitive" / "Occidental typically offers need-based aid to only a small number of international applicants". 비용·재정지원 페이지에 ''100% demonstrated financial need met'' 명시(전체 기준). 공식 사이트에 ED 합격자 최소 연 $15,000 장학금 언급.', 'https://www.oxy.edu/admission-aid/international-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (97, 'Pitzer College', '피처 칼리지', 37, 3, NULL, NULL, 'GPA 제출 신입생의 평균 고교 GPA 3.95, 석차 제출자 중 33%가 상위 10% (CDS 2025-26 C10·C12)', NULL, NULL, true, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 과정의 엄격성(rigor), 학업 GPA, 지원 에세이, 인성·개인적 자질, 그리고 지원자의 관심도(demonstrated interest)입니다. 추천서와 교외 활동은 ''Important'', 표준화 시험 점수는 ''Not Considered''(test-free)입니다. 입학처는 사회적 책임·상호문화 이해·학제 간 학습·학생 참여·환경 지속가능성이라는 5대 핵심 가치와의 공명을 보며, 시험 점수 대신 "성적표·교과 엄격성·학업 추세, 학업·개인 추천서, 학교·지역사회 활동 참여·리더십·근무 경력·개인 관심사"를 평가한다고 공식 명시합니다.', 'https://www.pitzer.edu/admission-aid/how-apply/first-year-applicants', 'test-free', '캘리포니아주 클레어몬트에 위치한 소규모 사립 리버럴 아츠 칼리지로, 클레어몬트 컬리지 컨소시엄(5C) 소속입니다.', '인구 약 3만 7천 명의 소도시 클레어몬트에 있으며 로스앤젤레스 다운타운에서 동쪽으로 약 55km(차로 45분~1시간), 연중 맑고 건조하며 여름이 덥고 겨울이 온화한 기후입니다.', true, true, false, false, '11월 중순', '1월 중순', NULL, '1월 중순', 'https://www.pitzer.edu/admission-aid/how-apply/first-year-applicants', '2026-08-22', ARRAY['rigor','gpa','essay','character','demonstrated_interest']::text[], 'https://www.pitzer.edu/documents/common-data-set-2025-2026', 'lac', 37, 'A small private liberal arts college in Claremont, California, and a member of the Claremont Colleges consortium.', 'Factors officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, application essay, character/personal qualities, and level of applicant''s interest. Recommendations and extracurricular activities are ''Important''; standardized test scores are ''Not Considered'' (test-free). The admission office officially states it looks for resonance with Pitzer''s five core values (social responsibility, intercultural understanding, interdisciplinary learning, student engagement, environmental sustainability) and, instead of test scores, evaluates "school transcripts, curriculum rigor, & academic trends," "academic & personal recommendation letters," and "involvement in school and community activities, leadership positions, work history, & personal interests."', 'Located in Claremont, a small city of about 37,000 roughly 55 km (45-60 minutes by car) east of downtown Los Angeles; sunny and dry year-round with hot summers and mild winters.', 'Average high school GPA 3.95 among first-years who submitted GPA; 33% of those who submitted class rank were in the top 10% (CDS 2025-26 C10/C12).', 46, 81824, '2025-26', NULL, NULL, true, NULL, '재정지원 페이지: "We meet 100% of students'' demonstrated need." 메리트 장학금은 Trustee Community Scholarship(연 $5,000, 갱신형)·Academic Achievement Scholarship(1회 $2,000)이 명시되어 있으나 국제학생 대상 여부는 미기재. 국제학생은 PIFAA(Pitzer International Financial Aid Application)로 need-based 신청(CSS Profile/FAFSA 제출 안 함).', 'https://www.pitzer.edu/admission-aid/financial-aid-information') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, kind, lac_rank, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url) values (98, 'Scripps College', '스크립스 칼리지', 37, 3, 1430, 1500, '석차 제출 신입생(전체의 13%) 중 63%가 고교 상위 10% (CDS 2025-26 C10)', NULL, false, false, ARRAY[]::text[], 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 과정의 엄격성(rigor), 학업 GPA, 지원 에세이, 인성·개인적 자질입니다. 추천서는 ''Important'', 표준화 시험 점수·면접·교외 활동·재능은 ''Considered'', 지원자의 관심도(demonstrated interest)와 동문 관계는 ''Not Considered''입니다. 입학처는 "학업 프로그램과 성취, 개인 에세이, 추천서, 교내외 활동"을 홀리스틱하게 검토하며 "지원자가 교실 안팎에서 스크립스 공동체의 일원으로 어떤 모습일지를 그려 본다"라고 공식 명시합니다.', 'https://www.scrippscollege.edu/admission/apply/first-year-applicants', 'test-optional', '캘리포니아주 클레어몬트에 위치한 소규모 사립 여자 리버럴 아츠 칼리지로, 클레어몬트 컬리지 컨소시엄(5C) 소속입니다.', '인구 약 3만 7천 명의 소도시 클레어몬트에 있으며 로스앤젤레스 다운타운에서 동쪽으로 약 55km(차로 45분~1시간), 연중 맑고 건조하며 여름이 덥고 겨울이 온화한 기후입니다.', true, true, false, false, '11월 중순', '1월 초', NULL, '1월 초', 'https://www.scrippscollege.edu/admission/apply/admission-deadlines', '2026-08-22', ARRAY['rigor','gpa','essay','character']::text[], 'https://www.scrippscollege.edu/assessir/wp-content/uploads/sites/30/CDS_2025-2026_FINAL_V3.pdf', 'lac', 37, 'A small private women''s liberal arts college in Claremont, California, and a member of the Claremont Colleges consortium.', 'Factors officially marked ''Very Important'' in CDS 2025-26 C7 are rigor of secondary school record, academic GPA, application essay, and character/personal qualities. Recommendations are ''Important''; standardized test scores, interview, extracurricular activities, and talent/ability are ''Considered''; level of applicant''s interest and alumni relation are ''Not Considered''. The admission office officially states it holistically reviews "academic program and performance; personal essay; recommendations; and co-curricular activities" and imagines "what the applicant would be like as a member of the Scripps community, engaged inside and outside of the classroom."', 'Located in Claremont, a small city of about 37,000 roughly 55 km (45-60 minutes by car) east of downtown Los Angeles; sunny and dry year-round with hot summers and mild winters.', '63% of first-years who submitted class rank (13% of the class) were in the top 10% of their high school class (CDS 2025-26 C10).', 15, 60832, '2024-25', NULL, NULL, true, NULL, '국제학생 재정지원 페이지: "A limited amount of financial aid is available to international students" / "Scripps College is need aware in our admission process" / 재정지원은 입학 시점에만 결정. 재정지원 메인 페이지: "Scripps meets 100 percent of a student''s institutionally determined financial need." 메리트 장학금의 국제학생 대상 여부는 미기재.', 'https://www.scrippscollege.edu/financialaid/information-for-international-students') on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url;
